"""Generate a measured population handoff, preserving gates and MC caveats."""
import sys,json,hashlib,collections
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent));import pop35_support as v
scores=[]
for p in v.OUT.glob('*/*.score.json'):
 r=json.loads(p.read_text());r['_path']=str(p);scores.append(r)
gates=[]
for p in v.OUT.glob('*/*.gate.json'):
 g=json.loads(p.read_text())
 if not g.get('gated'):continue
 st=Path(g['stem']);assert hashlib.sha256(st.with_suffix('.qasm').read_bytes()).hexdigest()==g['qasm_sha256'];assert g['allorders_acceptance']>=.5005
 gates.append(g)
gates.sort(key=lambda r:r['loss']);best=gates[0];p=Path(best['stem']);md=json.loads(p.with_suffix('.json').read_text())
lines=[f"**Best verified: `{p.relative_to(v.H)}` — all-orders {best['loss']:.12e}, acceptance {best['allorders_acceptance']:.9f}; judge PASS, XTIM FAST; MC3 mean {best.get('MC3_mean',float('nan')):.9e}.**",'', '# ST2 — v35b population', '',f"Base: MAIN/v35b, all-orders {v.a.BASE_LOSS:.12e}, acceptance {v.a.BASE_ACC:.12f}. Search acceptance floor: 0.5005. Best gain: {v.a.BASE_LOSS-best['loss']:.9e} ({100*(v.a.BASE_LOSS-best['loss'])/v.a.BASE_LOSS:.5f}%). {md['cx']} CX, R{md['R']}, native depth {md['native_depth']}.", '', '| Finalist under ST2 | All-orders loss | Acceptance | Judge acceptance / seconds | XTIM s/1e6 | MC3 mean |', '|---|---:|---:|---:|---:|---:|']
lines[6:6]=['Delivery: [best.qasm](best.qasm), [best.json](best.json), [best.verify.json](best.verify.json), byte-identical QASM to the source finalist above.', '', 'The winner keeps all five storage guards and the A/blue checks. Relative to v35b, it adds the later q7–q13 Z echo, folds the q15–q21 X echo readout into a q21 measurement at tick32, and replaces the q20–q26 Z echo with a later q20–q21 X echo. Guard274/275 use measured initialization parities; selected early known-zero checks are restored; q1 at tick7 uses a checked X measurement; Tdag moves from q16 at34 to q22 at37. The q15 terminal instrument remains. These are the actual native diff, not an additive estimate.', '']
for g in gates:
 assert isinstance(g.get('MC3'),dict)and set(g['MC3'])=={'0','1000','2000'},('MC3 unfinished',g['stem'])
 lines.append(f"| `{Path(g['stem']).relative_to(v.H)}` | {g['loss']:.12e} | {g['allorders_acceptance']:.9f} | {g['judge_acceptance']:.6f} / {g['judge_seconds']:.3f} | {g['speed']['median_seconds_per_1e6']:.3f} | {g['MC3_mean']:.9e} |")
lines+=['',f'Total scored alternatives: {len(scores)}; acceptance-feasible numerical results: {sum(r.get("eligible",False) and "loss"in r for r in scores)}. There are {len(list(v.OUT.glob("*/generation_*.json")))} complete population generation checkpoints. The initial zebra run migrated only after generation7 was fully joined and saved; both final islands then stopped after two nonimproving generations.', '', 'All finalists above passed judge1e6, XTIM FAST and MC3 (100M shots at seeds0/1000/2000). All-orders loss ranks this supported zero-frame family; MC3 estimates and SEMs are preserved, without claiming they resolve each small improvement. Hashes bind gates to the delivered QASM. No server runtime or global optimum is claimed.','','Search evidence:','']
for group in sorted(set(Path(r['_path']).parent.name for r in scores)):
 rr=[r for r in scores if Path(r['_path']).parent.name==group];good=[r for r in rr if r.get('eligible')and'loss'in r]
 lines.append(f"- `{group}/`: {len(rr)} scored; {len(good)} acceptance-feasible; "+(f"best {min(r['loss']for r in good):.12e}."if good else'no feasible loss result.'))
for p in sorted(v.OUT.glob('*/generation_*.json')):
 r=json.loads(p.read_text());lines.append(f"- `{p.relative_to(v.OUT)}`: best {r['best']['loss']:.12e}, gain {r['improvement']:.6e}, consecutive nonimproving generations {r['stagnant']}.")
lines+=['','The population uses full 72-observable canonical all-orders fitness and exact acceptance before evaluating loss. It retains low-loss elites and acceptance alternatives; all complete crossovers are repriced. Unsupported or nondeterministic circuits are recorded as failures. No first-order or truncated-order rank filter is applied. The initial reusable scorer also calculated a single-fault diagnostic; subsequent workers omit that unused diagnostic and keep the identical all-orders calculation.','','Moves exercised: slack retiming, commuting gate reordering, reset/checked-measurement choices, MX/MZ helper bases, guard/echo endpoints, neighboring helper substitutions, guard274 removal plus replacement gadgets, detector row add/remove, new idle echoes, whole-window timing, terminal readout-edge changes, and crossovers of measured improvements. Helper substitutions shrink to a legal available interval when the original full window is occupied. All physical rewrites remain subject to native schedule, geometry and ideal correctness checks.','','FRESH’s measured timing recipes and WAITPROT’s current menu were ported as native patches; standalone SX and timing sweeps were not repeated. New record IDs are reassigned. The released q7 helper and measured-X initialization at q1 were combined through the evolving population. Menus and rejected ports are preserved under `patches_catalog.json`, `patches.json`, seed logs and generation summaries.','','The winning sparse-kernel cutoff omission bound is 1.1970659100562574e-14; it excludes floating-point roundoff. The sparse evaluator is byte-identical to MAIN’s current evaluator.','','The final phase screen tested all eight masks of the three legacy transfer choices on the current schedule: the unchanged mask and q16-to-q22 relocation passed; the other six fixed variants failed ideal detector determinism. The q16-to-q22 gain is 4.658454349e-10 in all-orders loss, too small for these MC draws to resolve. No broader phase-transfer impossibility is claimed.','','`best_changes.json` records the exact final changes from v35b. `all_results.json` indexes every numerical result and rejection. Prior acceptance knapsack work remains in [REPORT_before_population.md](pop35b/REPORT_before_population.md).','','Complete: all ST2 search and validation jobs exited. All writes remained under ST2. No submissions, credentials, commits, pushes or collaboration tools were used.']
(v.H/'REPORT.md').write_text('\n'.join(lines)+'\n');(v.OUT/'all_results.json').write_text(json.dumps(dict(base_loss=v.a.BASE_LOSS,base_acceptance=v.a.BASE_ACC,scores=scores,gates=gates),indent=2))
patch=v.k.patches(v.C.read(v.OUT/'base'),v.C.read(Path(best['stem'])));(v.OUT/'best_changes.json').write_text(json.dumps({key:sorted([list(x)if isinstance(x,tuple)else x for x in val],key=str)for key,val in patch.items()},indent=2))
(v.OUT/'STATUS.md').write_text('Complete. Final report: ../REPORT.md. All search and verification jobs exited.\n')
print('BEST',best['stem'],best['loss'],best['allorders_acceptance'],best['MC3_mean'],'scores',len(scores),'finalists',len(gates))
